package com.securebank.web;

import com.securebank.db.Database;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/** HTML helpers and the page shell (sidebar, top bar, toasts). The whole UI is generated by Java. */
public final class Html {
    private Html() { }

    public record Flash(String kind, String text, String sub) { }

    private static final String[][] NAV = {
            {"home", "/", "📊", "Dashboard"},
            {"account", "/account", "👤", "My Account"},
            {"open", "/open", "✨", "Open Account"},
            {"lab", "/lab", "🧪", "OOP Lab"},
            {"admin", "/admin", "🔐", "Admin"}
    };

    // ---------------------------------------------------------------- formatting
    public static String esc(Object o) {
        if (o == null) return "";
        String s = String.valueOf(o);
        StringBuilder sb = new StringBuilder(s.length() + 8);
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '&' -> sb.append("&amp;");
                case '<' -> sb.append("&lt;");
                case '>' -> sb.append("&gt;");
                case '"' -> sb.append("&quot;");
                case '\'' -> sb.append("&#39;");
                default -> sb.append(c);
            }
        }
        return sb.toString();
    }

    /** Indian rupee format with lakh/crore grouping, e.g. ₹12,34,567.50 */
    public static String inr(double v) {
        boolean whole = v == Math.rint(v);
        String plain = BigDecimal.valueOf(Math.abs(v)).setScale(whole ? 0 : 2, RoundingMode.HALF_UP).toPlainString();
        String intPart = plain, frac = "";
        int dot = plain.indexOf('.');
        if (dot >= 0) { intPart = plain.substring(0, dot); frac = plain.substring(dot); }
        StringBuilder g = new StringBuilder();
        if (intPart.length() > 3) {
            String head = intPart.substring(0, intPart.length() - 3);
            String tail = intPart.substring(intPart.length() - 3);
            for (int i = 0; i < head.length(); i++) {
                if (i > 0 && (head.length() - i) % 2 == 0) g.append(',');
                g.append(head.charAt(i));
            }
            g.append(',').append(tail);
        } else g.append(intPart);
        return (v < 0 && !plain.equals("0") ? "-" : "") + "\u20B9" + g + frac;
    }

    public static String ago(long ms) {
        long s = Math.max(1, (System.currentTimeMillis() - ms) / 1000);
        if (s < 60) return s + "s ago";
        if (s < 3600) return (s / 60) + "m ago";
        if (s < 86400) return (s / 3600) + "h ago";
        return (s / 86400) + "d ago";
    }

    public static double num(Object o) {
        return o instanceof Number n ? n.doubleValue() : 0;
    }

    // ---------------------------------------------------------------- page shell
    public static String page(String active, String title, List<Flash> flashes, String body, boolean autoRefresh) {
        StringBuilder sb = new StringBuilder(16_384);
        sb.append("<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">")
          .append("<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">")
          .append(autoRefresh ? "<meta http-equiv=\"refresh\" content=\"30\">" : "")
          .append("<title>").append(esc(title)).append(" · SecureBank</title>")
          .append("<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E🛡️%3C/text%3E%3C/svg%3E\">")
          .append("<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">")
          .append("<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>")
          .append("<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Space+Mono:wght@400;700&display=swap\" rel=\"stylesheet\">")
          .append("<link rel=\"stylesheet\" href=\"/style.css\"></head><body><div class=\"app\">");

        // sidebar
        sb.append("<aside class=\"side\"><a class=\"brand\" href=\"/\"><span class=\"logo\">🛡️</span><span><b>Secure</b>Bank</span></a><nav id=\"tabs\">");
        for (String[] n : NAV) {
            sb.append("<a href=\"").append(n[1]).append("\"").append(n[0].equals(active) ? " class=\"on\"" : "").append("><i>")
              .append(n[2]).append("</i><span>").append(n[3]).append("</span></a>");
        }
        sb.append("</nav><div class=\"tip\"><b>💡 Viva tip</b><p>Open the <u>OOP Lab</u> and run the same <code>withdraw()</code> ")
          .append("on Savings and Current to show polymorphism live.</p></div></aside>");

        // content
        sb.append("<div class=\"content\"><div class=\"topbar\"><h2>").append(esc(title)).append("</h2>")
          .append("<div class=\"dbbadge\"><i></i>").append(esc(Database.label())).append("</div></div><main>")
          .append(body).append("</main><footer>Built with Java 17 · server-side rendered UI · JDBC · PostgreSQL / H2 · zero JavaScript</footer></div></div>");

        // toasts (they fade out with a CSS animation)
        sb.append("<div id=\"toasts\">");
        for (Flash f : flashes) {
            sb.append("<div class=\"toast ").append(esc(f.kind())).append("\">").append(esc(f.text()));
            if (f.sub() != null && !f.sub().isEmpty()) sb.append("<small>").append(esc(f.sub())).append("</small>");
            sb.append("</div>");
        }
        sb.append("</div></body></html>");
        return sb.toString();
    }

    public static String errorBody(String message) {
        return "<div class=\"glass narrow\"><h2>😵 Oops</h2><p class=\"muted\">" + esc(message)
             + "</p><a class=\"btn primary wide\" href=\"/\">Back to dashboard</a></div>";
    }
}
